INSERT INTO brands (id,name,description) VALUES ('hq-beauty','H.Q.Beauty','Швейцарський бренд космецевтичних засобів для догляду за шкірою обличчя, тіла та волосся. Лінійки для волосся поєднують натуральні й органічні компоненти з функціональними комплексами.') ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('hq-beauty-daily-care','hq-beauty','Daily Care','Делікатний щоденний догляд для всіх типів волосся','Серія з органічним екстрактом листя та стебел вівса для частого делікатного догляду. Підходить усім типам волосся, зокрема тонкому й делікатному.','["Усі типи волосся","Тонке","Делікатне"]','["Щоденний догляд","Делікатне очищення","Зволоження"]','["Пом’якшує волосся","Зволожує","Підтримує еластичність","Надає блиску"]','["Щоденний догляд","Вівсяний екстракт","Делікатний догляд"]','/images/hq-beauty/hq-beauty-daily-care.webp') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('hq-beauty-nourish-dry-and-brittle-hair','hq-beauty','Nourish Dry and Brittle Hair','Живильний догляд для сухого, ламкого, тьмяного та кучерявого волосся','Серія з органічним екстрактом волошки для зволоження, захисту й живлення сухого, ламкого, тьмяного та кучерявого волосся.','["Сухе","Ламке","Тьмяне","Кучеряве"]','["Живлення","Зволоження","Зміцнення"]','["Допомагає запобігати ламкості","Пом’якшує волосся","Підвищує еластичність","Надає блиску"]','["Живлення","Волошка","Сухе волосся"]','/images/hq-beauty/hq-beauty-nourish-dry-and-brittle-hair.webp') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('hq-beauty-keep-hair-color','hq-beauty','Keep Hair Color','Захист кольору фарбованого волосся та термозахист','Серія з органічним екстрактом листя червоного винограду для збереження яскравості кольору, пом’якшення та захисту волосся.','["Фарбоване","Усі типи волосся"]','["Збереження кольору","Захист від вимивання пігменту","Термозахист"]','["Зберігає яскравість кольору","Надає блиску","Пом’якшує","Захищає під час укладання"]','["Фарбоване волосся","Захист кольору","Термозахист"]','/images/hq-beauty/hq-beauty-keep-hair-color.webp') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('hq-beauty-restore-damaged-hair','hq-beauty','Restore Damaged Hair','Відновлювальний догляд для пошкодженого волосся','Серія з органічним гідролізованим екстрактом каштана для відновлення структури, зміцнення, живлення та зволоження пошкодженого волосся.','["Пошкоджене","Ламке"]','["Відновлення структури","Зміцнення","Захист від подальших пошкоджень"]','["Підвищує еластичність","Розгладжує","Зволожує","Повертає блиск"]','["Відновлення","Каштан","Пошкоджене волосся"]','/images/hq-beauty/hq-beauty-restore-damaged-hair.webp') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO product_lines (id,brand_id,name,short_description,description,hair_types,purposes,benefits,keywords,image) VALUES ('hq-beauty-hair-loss-control','hq-beauty','Hair Loss Control','Догляд для слабкого волосся та волосся, схильного до випадіння','Серія з органічним екстрактом розмарину для догляду за шкірою голови, зміцнення волосся та підтримки волосяних фолікулів.','["Слабке","Схильне до випадіння","Усі типи волосся"]','["Контроль випадіння","Зміцнення волосся","Догляд за шкірою голови"]','["Сприяє зміцненню волосся","Стимулює кровообіг шкіри голови","Підтримує волосяні фолікули"]','["Випадіння","Розмарин","Зміцнення"]','/images/hq-beauty/hq-beauty-hair-loss-control.webp') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,name=excluded.name,short_description=excluded.short_description,description=excluded.description,hair_types=excluded.hair_types,purposes=excluded.purposes,benefits=excluded.benefits,keywords=excluded.keywords,image=excluded.image;
INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('hq-beauty-daily-care-shampoo','hq-beauty','hq-beauty-daily-care','Daily Care Shampoo','Шампунь','Шампунь для дбайливого очищення волосся та навіть чутливої шкіри голови. Формула підтримує природний гідроліпідний баланс і надає тонізувальний та освіжальний ефект.','Делікатне щоденне очищення волосся та шкіри голови','/images/hq-beauty/hq-beauty-daily-care-shampoo.webp','Нанести на вологе волосся та шкіру голови, спінити масажними рухами й рівномірно розподілити по довжині. Ретельно змити водою.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
