INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('hq-beauty-keep-hair-color-conditioner','hq-beauty','hq-beauty-keep-hair-color','Keep Hair Color Conditioner','Кондиціонер','Кондиціонер для захисту кольору фарбованого волосся. Зволожує, вирівнює кутикулу, надає м’якості й блиску та полегшує розчісування без обтяження.','Захист кольору та кондиціонування фарбованого волосся','/images/hq-beauty/hq-beauty-keep-hair-color-conditioner.webp','Нанести на чисте вологе волосся й рівномірно розподілити по довжині. Залишити на 3–5 хвилин, потім ретельно змити водою.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
