INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('hq-beauty-hair-loss-control-shampoo','hq-beauty','hq-beauty-hair-loss-control','Hair Loss Control Shampoo','Шампунь','Шампунь для очищення та зміцнення слабкого волосся або волосся, схильного до випадіння. Тонізує шкіру голови, стимулює кровообіг і підтримує волосяні фолікули.','Очищення та зміцнення волосся, схильного до випадіння','/images/hq-beauty/hq-beauty-hair-loss-control-shampoo.webp','Нанести на вологе волосся та шкіру голови, спінити масажними рухами й рівномірно розподілити по довжині. Ретельно змити водою.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
