INSERT INTO products (id,brand_id,line_id,name,category,description,purpose,image,usage) VALUES ('hq-beauty-hair-loss-control-strengthening-complex','hq-beauty','hq-beauty-hair-loss-control','Hair Loss Control Strengthening Complex','Зміцнювальний комплекс','Незмивний комплекс для шкіри голови та волосся, схильного до випадіння. Допомагає зміцнювати волосяні фолікули й підтримувати фізіологічний ріст волосся.','Зміцнення волосся та догляд за шкірою голови при схильності до випадіння','/images/hq-beauty/hq-beauty-hair-loss-control-strengthening-complex.webp','Нанести на суху чисту шкіру голови по проділах і розподілити м’якими круговими масажними рухами 15–20 секунд, приділяючи увагу кореням і зонам випадіння. Не змивати; застосовувати після миття, але не менше 1–2 разів на тиждень протягом 2 місяців.') ON CONFLICT(id) DO UPDATE SET brand_id=excluded.brand_id,line_id=excluded.line_id,name=excluded.name,category=excluded.category,description=excluded.description,purpose=excluded.purpose,image=excluded.image,usage=excluded.usage;
